'use strict';

// MODULES //

var pow = require( '@stdlib/math/base/special/pow' );
var abs = require( '@stdlib/math/base/special/abs' );
var max = require( '@stdlib/math/base/special/max' );


// VARIABLES //

var PRODUCT_LIMIT = pow( 2.0, 1023 );


// MAIN //

/**
* Returns the largest exponent `s` for which the product overflow guard does not trip when `max|a|·max|b| = 2^s` (and `β = 0`).
*
* ## Notes
*
* -   The guard delegates to the conventional algorithm unless `max|a|·max|b|·K·4.5^L·max(1,|α|) < 2^1023`.
*
* @private
* @param {PositiveInteger} K - inner dimension
* @param {PositiveInteger} L - number of recursion levels
* @param {number} alpha - scalar constant
* @returns {integer} exponent
*/
function guardThreshold( K, L, alpha ) {
	var c;
	var s;

	c = K * pow( 4.5, L ) * max( 1.0, abs( alpha ) );
	s = 0;
	while ( pow( 2.0, s+1 ) * c < PRODUCT_LIMIT ) {
		s += 1;
	}
	return s;
}


// EXPORTS //

module.exports = guardThreshold;
